import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    .reg .u32 %r<40>;
    .reg .u64 %rd<40>;
    .reg .f32 %f<12>;
    .reg .pred %p<8>;
    .shared .align 4 .f32 sA[256];
    .shared .align 4 .f32 sB0[256];
    .shared .align 4 .f32 sB1[256];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [N];
    ld.param.u32 %r3, [K];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r4, %ctaid.x;
    mov.u32 %r5, %ntid.x;
    mov.u32 %r6, %tid.x;        // tx
    mul.lo.s32 %r7, %r4, 32;    // ctaid.x * N_TILE(32)
    add.s32 %r7, %r7, %r6;      // col0
    add.s32 %r30, %r7, 16;      // col1 = col0 + 16
    mov.u32 %r8, %ctaid.y;
    mov.u32 %r9, %ntid.y;
    mov.u32 %r10, %tid.y;       // ty
    mad.lo.s32 %r11, %r8, %r9, %r10; // row
    setp.ge.s32 %p1, %r7, %r2;
    setp.ge.s32 %p2, %r11, %r1;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;
    mov.u32 %r12, %ctaid.z;   // split-K index
    mov.u32 %r13, %nctaid.z;  // number of splits
    div.u32 %r14, %r3, %r13;  // chunk = K / splits (host guarantees exact division)
    mul.lo.s32 %r15, %r12, %r14; // k_start
    add.s32 %r16, %r15, %r14;    // k_end
    mov.f32 %f1, 0f00000000;   // acc0 (col0)
    mov.f32 %f7, 0f00000000;   // acc1 (col1)
    mov.u32 %r21, sA;
    mov.u32 %r22, sB0;
    mov.u32 %r23, sB1;
    mov.u32 %r17, %r15;  // k_tile = k_start
TILE_LOOP:
    setp.ge.s32 %p4, %r17, %r16;
    @%p4 bra TILE_LOOP_END;
    // load A element: A[row][k_tile+tx]
    add.s32 %r18, %r17, %r6;
    cvt.s64.s32 %rd4, %r11;
    cvt.s64.s32 %rd5, %r3;
    mul.lo.s64 %rd6, %rd4, %rd5;
    cvt.s64.s32 %rd7, %r18;
    add.s64 %rd8, %rd6, %rd7;
    shl.b64 %rd9, %rd8, 2;
    add.s64 %rd10, %rd1, %rd9;
    ld.global.f32 %f2, [%rd10];
    // load B0 element: B[k_tile+ty][col0]
    add.s32 %r19, %r17, %r10;
    cvt.s64.s32 %rd11, %r19;
    cvt.s64.s32 %rd12, %r2;
    mul.lo.s64 %rd13, %rd11, %rd12;
    cvt.s64.s32 %rd14, %r7;
    add.s64 %rd15, %rd13, %rd14;
    shl.b64 %rd16, %rd15, 2;
    add.s64 %rd17, %rd2, %rd16;
    ld.global.f32 %f3, [%rd17];
    // load B1 element: B[k_tile+ty][col1]
    cvt.s64.s32 %rd25, %r30;
    add.s64 %rd26, %rd13, %rd25;
    shl.b64 %rd27, %rd26, 2;
    add.s64 %rd28, %rd2, %rd27;
    ld.global.f32 %f4, [%rd28];
    // stage tiles into shared memory (cooperative, coalesced loads)
    mad.lo.u32 %r20, %r10, 16, %r6;     // idx = ty*16+tx
    mad.lo.u32 %r24, %r20, 4, %r21;     // addr_sA
    st.shared.f32 [%r24], %f2;
    mad.lo.u32 %r25, %r20, 4, %r22;     // addr_sB0
    st.shared.f32 [%r25], %f3;
    mad.lo.u32 %r26, %r20, 4, %r23;     // addr_sB1
    st.shared.f32 [%r26], %f4;
    bar.sync 0;
    mov.u32 %r27, 0;   // kk
INNER_LOOP:
    setp.ge.s32 %p5, %r27, 16;
    @%p5 bra INNER_DONE;
    mad.lo.u32 %r28, %r10, 16, %r27;    // idxA = ty*16+kk
    mad.lo.u32 %r31, %r28, 4, %r21;     // addrA2
    ld.shared.f32 %f5, [%r31];
    mad.lo.u32 %r29, %r27, 16, %r6;     // idxB = kk*16+tx
    mad.lo.u32 %r32, %r29, 4, %r22;     // addrB0_2
    ld.shared.f32 %f6, [%r32];
    mad.lo.u32 %r33, %r29, 4, %r23;     // addrB1_2
    ld.shared.f32 %f8, [%r33];
    fma.rn.f32 %f1, %f5, %f6, %f1;      // acc0 += a*b0
    fma.rn.f32 %f7, %f5, %f8, %f7;      // acc1 += a*b1
    add.s32 %r27, %r27, 1;
    bra INNER_LOOP;
INNER_DONE:
    bar.sync 0;
    add.s32 %r17, %r17, 16;
    bra TILE_LOOP;
TILE_LOOP_END:
    cvt.s64.s32 %rd18, %r11;
    cvt.s64.s32 %rd19, %r2;
    mul.lo.s64 %rd20, %rd18, %rd19;
    cvt.s64.s32 %rd21, %r7;
    add.s64 %rd22, %rd20, %rd21;
    shl.b64 %rd23, %rd22, 2;
    add.s64 %rd24, %rd3, %rd23;
    atom.global.add.f32 %f9, [%rd24], %f1;
    setp.ge.s32 %p6, %r30, %r2;
    @%p6 bra DONE;
    cvt.s64.s32 %rd29, %r30;
    add.s64 %rd30, %rd20, %rd29;
    shl.b64 %rd31, %rd30, 2;
    add.s64 %rd32, %rd3, %rd31;
    atom.global.add.f32 %f10, [%rd32], %f7;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B) with a large K dimension,
    implemented via a custom PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"

        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions must match"

        splits = 1
        max_splits = 64
        while splits < max_splits and K % (splits * 2) == 0:
            splits *= 2
        C = torch.zeros((M, N), device=A.device, dtype=A.dtype)

        module = _get_ptx_module()

        block = (16, 16, 1)
        N_TILE = 32  # each thread computes 2 output columns (register/thread-level tiling)
        grid = ((N + N_TILE - 1) // N_TILE, (M + block[1] - 1) // block[1], splits)

        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, i32(M), i32(N), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

